// Flatten all feed items, tag with source, filter by age
const MAX_AGE_HOURS = 48;
const cutoff = Date.now() - (MAX_AGE_HOURS * 60 * 60 * 1000);

const items = [];
for (const item of $input.all()) {
  const pubDate = new Date(item.json.pubDate || item.json.isoDate || item.json.date);
  if (pubDate.getTime() > cutoff) {
    items.push({
      json: {
        title: item.json.title,
        link: item.json.link,
        pubDate: pubDate.toISOString(),
        source: item.json._feedName || 'unknown',
        snippet: (item.json.contentSnippet || item.json.content || '').substring(0, 500)
      }
    });
  }
}

return items;

// Parse Claude's filter response and check score threshold
const MIN_SCORE = 0.6;

const response = $input.first().json;
const content = response.content?.[0]?.text || '{}';

let parsed;
try {
  // Extract JSON from response (may be wrapped in markdown code block)
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  parsed = { score: 0, reasoning: 'Failed to parse filter response' };
}

return [{
  json: {
    ...parsed,
    original_title: $('Log Discovery').first().json.source_title,
    original_url: $('Log Discovery').first().json.source_url,
    pipeline_run_id: $('Log Discovery').first().json.id,
    passes_filter: parsed.score >= MIN_SCORE
  }
}];

// Extract text from HTML source page
const html = $input.first().json.data || $input.first().json.body || '';

// Strip HTML tags, get text content
const text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 8000);

return [{
  json: {
    source_text: text,
    original_url: $('Parse Filter Score').first().json.original_url,
    original_title: $('Parse Filter Score').first().json.original_title,
    suggested_section: $('Parse Filter Score').first().json.suggested_section,
    suggested_angle: $('Parse Filter Score').first().json.suggested_angle,
    pipeline_run_id: $('Parse Filter Score').first().json.pipeline_run_id
  }
}];

// Parse writer output
const response = $input.first().json;
const content = response.content?.[0]?.text || '{}';

let article;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  article = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  throw new Error('Failed to parse writer output: ' + e.message);
}

return [{
  json: {
    ...article,
    pipeline_run_id: $('Extract Source Text').first().json.pipeline_run_id
  }
}];

// Parse editor output and prepare for publishing
const response = $input.first().json;
const content = response.content?.[0]?.text || '{}';

let article;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  article = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  throw new Error('Failed to parse editor output: ' + e.message);
}

// Use editor's status recommendation or default to review
const status = article.status === 'scheduled' ? 'published' : 'review';

return [{
  json: {
    title: article.title,
    subtitle: article.subtitle,
    section: article.section,
    body_md: article.body_md,
    excerpt: article.excerpt,
    tags: article.tags || [],
    slug: article.suggested_slug || article.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    reading_time_min: article.reading_time_min,
    source_urls: article.source_urls || [],
    status: status,
    pipeline_run_id: $('Parse Draft').first().json.pipeline_run_id,
    editor_notes: article.editor_notes || null
  }
}];

// Merge Unsplash result with article data
const article = $('Parse Edited Article').first().json;
const unsplash = $input.first().json;

const photo = unsplash.results?.[0];

if (photo) {
  article.cover_image_url = photo.urls?.regular || photo.urls?.full;
  article.cover_image_alt = photo.alt_description || article.title;
  article.cover_image_credit = `Photo by ${photo.user?.name} on Unsplash`;
}

return [{ json: article }];

// Build the RSS feed list for iteration
const feeds = [
  { url: 'https://spacenews.com/feed/', name: 'SpaceNews' },
  { url: 'https://arstechnica.com/space/feed/', name: 'Ars Technica Space' },
  { url: 'https://www.nasaspaceflight.com/feed/', name: 'NASASpaceFlight' },
  { url: 'https://www.space.com/feeds/all', name: 'Space.com' },
  { url: 'https://spacepolicyonline.com/feed/', name: 'Space Policy Online' },
  { url: 'https://europeanspaceflight.com/feed/', name: 'European Spaceflight' },
  { url: 'https://payloadspace.com/feed/', name: 'Payload Space' },
  { url: 'https://blogs.nasa.gov/artemis/feed/', name: 'NASA Artemis Blog' },
  { url: 'https://blogs.nasa.gov/spacestation/feed/', name: 'NASA ISS Blog' },
  { url: 'https://www.cnbc.com/space/rss', name: 'CNBC Space' }
];

return feeds.map(f => ({ json: f }));

// Deduplication: check if source_url already exists in pipeline_runs
const url = $input.first().json.link;
const checkUrl = `https://gyggbhepbfocvaeyemuu.supabase.co/rest/v1/pipeline_runs?source_url=eq.${encodeURIComponent(url)}&select=id&limit=1`;

// We'll use a simple flag — the HTTP dedup check happens in the next node
return [{ json: { ...$input.first().json, needs_dedup_check: true } }];
